select * from calender



	and mem_id = #{memId}

		and type_cd = #{typeCd}


		AND (
		PLACE LIKE '%' || #{keyword} || '%'
		OR CAL_TEXT LIKE '%' || #{keyword} || '%'
		)

select * from calender




	and (
	mem_id = #{memId}
	or sharing_cd = '01CALSHARE'
	)

		and type_cd = #{typeCd}


order by cal_start
